header.script:
document.addEventListener("DOMContentLoaded", function() {
    const scrollContainer = document.querySelector('#_hmenu');
    const btnNext = document.querySelector('#menu_next');
    const btnPrev = document.querySelector('#menu_prev');
    const activeMenuItem = scrollContainer.querySelector("li.active");

    function updateButtonVisibility() {
        const scrollLeft = scrollContainer.scrollLeft;
        const maxScrollLeft = scrollContainer.scrollWidth - scrollContainer.clientWidth;

        if (maxScrollLeft <= 0) {
            btnPrev.style.display = 'none';
            btnNext.style.display = 'none';
        } else {
            btnPrev.style.display = scrollLeft <= 0 ? 'none' : 'inline-block';
            btnNext.style.display = scrollLeft >= maxScrollLeft - 1 ? 'none' : 'inline-block';
        }
    }

    if (activeMenuItem) {
        const containerRect = scrollContainer.getBoundingClientRect();
        const itemRect = activeMenuItem.getBoundingClientRect();
        const offset = itemRect.left - containerRect.left + scrollContainer.scrollLeft;
        const scrollTo = offset - (containerRect.width / 2) + (itemRect.width / 2);
        setTimeout(() => {
            scrollContainer.scrollTo({
                left: scrollTo,
                behavior: "smooth"
            });
            updateButtonVisibility();
        }, 50);
    } else {
        updateButtonVisibility();
    }

    btnNext.addEventListener('click', () => {
        scrollContainer.scrollBy({
            left: 200,
            behavior: 'smooth'
        });
    });

    btnPrev.addEventListener('click', () => {
        scrollContainer.scrollBy({
            left: -200,
            behavior: 'smooth'
        });
    });

    scrollContainer.addEventListener('scroll', updateButtonVisibility);
    window.addEventListener('resize', updateButtonVisibility);

    // Hover
    let hoverTimeout;
    const subcontainer = document.getElementById('submenu-container');

    document.querySelectorAll('.navigation li[data-slug]').forEach(item => {
        item.addEventListener('mouseenter', function() {
            clearTimeout(hoverTimeout);

            const slug = this.dataset.slug;
            const submenu = subcontainer.querySelector(`ul[data-slug="${slug}"]`);

            const rect = this.getBoundingClientRect();
            subcontainer.style.left = `${rect.left}px`;

            document.querySelectorAll('#submenu-container ul').forEach(ul => {
                ul.classList.remove('active');
            });

            subcontainer.classList.add('show');
            submenu.classList.add('active');
        });

        item.addEventListener('mouseleave', function() {
            hoverTimeout = setTimeout(() => {
                if (!subcontainer.matches(':hover')) {
                    subcontainer.classList.remove('show');
                }
            }, 150);
        });
    });

    subcontainer.addEventListener('mouseenter', () => {
        clearTimeout(hoverTimeout);
    });

    subcontainer.addEventListener('mouseleave', () => {
        subcontainer.classList.remove('show');
    });

    document.querySelector('.navbar').addEventListener('scroll', updateSubmenuPosition);

    function updateSubmenuPosition() {
        const activeItem = document.querySelector('.navigation li[data-slug]:hover');
        if (activeItem && subcontainer.classList.contains('show')) {
            const rect = activeItem.getBoundingClientRect();
            subcontainer.style.left = `${rect.left}px`;
        }
    }
});

html.script:
document.addEventListener("DOMContentLoaded", function() {
    const images = document.querySelectorAll("img.ll");

    images.forEach(img => {
        const skeleton = img.closest(".skeleton");

        const lowResSrc = img.getAttribute("src"); // Ảnh chất lượng thấp
        const highResSrc = img.getAttribute("data-src"); // Ảnh gốc chất lượng cao

        if (highResSrc) {
            const tempImg = new Image(); // Tạo ảnh tạm để kiểm tra load
            tempImg.src = highResSrc;

            tempImg.onload = function() {
                img.src = highResSrc; // Chỉ thay đổi khi ảnh đã load xong
                img.removeAttribute("data-src");

                if (skeleton) {
                    skeleton.classList.remove("skeleton");
                }
            };
        }
    });
});

var swiper = new Swiper(".slideSwiper", {
    effect: "fade",
    fadeEffect: {
        crossFade: true
    },
    autoplay: {
        delay: 8000,
        disableOnInteraction: false
    },
    speed: 800,
    loop: true,
    on: {
        slideChangeTransitionStart: function() {
            // Xoá animation cũ để reset lại
            const allSlides = document.querySelectorAll('.swiper-slide img');
            allSlides.forEach(img => {
                img.style.animation = "none";
                img.offsetHeight; // trigger reflow
                img.style.animation = "";
            });
        }
    }
});

