var logoSwiper = new Swiper(".saleSwiper", {
    slidesPerView: 3,
    spaceBetween: 24,
    loop: false,
    autoplay: {
        delay: 5000,
        disableOnInteraction: false
    },
    pagination: {
        el: ".swiper-pagination",
        clickable: true
    },
    navigation: {
        nextEl: ".swiper-button-next-2",
        prevEl: ".swiper-button-prev-2",
    },
    breakpoints: {
        0: {
            slidesPerView: 1,
            spaceBetween: 12,
        },
        375: {
            slidesPerView: 1,
            spaceBetween: 12,
        },
        425: {
            slidesPerView: 1.5,
            spaceBetween: 12,
        },
        768: {
            slidesPerView: 2,
            spaceBetween: 12,
        },
        1024: {
            slidesPerView: 2,
            spaceBetween: 12,
        },
        1200: {
            slidesPerView: 3,
            spaceBetween: 24,
        },
    },
    on: {
        slideChangeTransitionStart: function() {
            // Ẩn toàn bộ .po_a
            document.querySelectorAll('.saleSwiper .po_a').forEach(el => {
                el.classList.remove('show');
            });
        },
        slideChangeTransitionEnd: function() {
            // Sau 1 giây, hiện .po_a của slide đang active
            setTimeout(() => {
                const activeSlide = document.querySelector('.saleSwiper .swiper-slide-active .po_a');
                if (activeSlide) {
                    activeSlide.classList.add('show');
                }
            }, 100); // Delay 1 giây
        }
    }
})

